  const successes2 = numericData2.reduce((sum5, x8) => sum5 + x8, 0);
  const n1 = numericData1.length;
  const n2 = numericData2.length;
  const contingencyTable = [
    [
      successes1,
      n1 - successes1,
    ],
    [
      successes2,
      n2 - successes2,
    ],
  ];
